 paper(i,f'SCI-REPO-Y10-ARAN-STARPOSTER-{i}',10,'Earth and Space Sciences','Stellar-life-cycle poster',key=i,sourceyear=2015 if i==307 else 2016 if i in[323,324]else None,school='Aranmore')
